import os, glob

dl = os.path.expanduser('~/Downloads')
pdfs = []
for root, dirs, files in os.walk(dl):
    # 不深入太深的隐藏目录
    dirs[:] = [d for d in dirs if not d.startswith('.')]
    for f in files:
        if f.lower().endswith('.pdf'):
            p = os.path.join(root, f)
            try:
                st = os.stat(p)
                pdfs.append((p, st.st_size))
            except Exception as e:
                print('ERR', p, e)

pdfs.sort(key=lambda x: -x[1])
print(f'Total PDFs: {len(pdfs)}')
for p, s in pdfs[:60]:
    print(f'{s:>12,}  {p}')
if len(pdfs) > 60:
    print(f'... and {len(pdfs)-60} more')

import os

dl = os.path.expanduser('~/Downloads')
pdfs = []
for root, dirs, files in os.walk(dl):
    dirs[:] = [d for d in dirs if not d.startswith('.')]
    for f in files:
        if f.lower().endswith('.pdf'):
            pdfs.append(os.path.join(root, f))

for p in sorted(pdfs, key=os.path.basename):
    with open(p, 'r', errors='replace') as fh:
        lines = [l.strip() for l in fh.readlines() if l.strip().startswith('%') and 'EOF' not in l and 'placeholder' not in l and 'PDF' not in l]
    print(f'{os.path.basename(p):<45} | {" ".join(lines)}')

